'QZ_Tray_Printer' => 'QZ Tray (طابعة على هذا الحاسوب)',
'QZ_Printer_Name_Hint' => 'اسم الطابعة كما يظهر على الحاسوب الذي يعمل عليه QZ Tray. اتركه فارغًا لاستخدام الطابعة الافتراضية لذلك الحاسوب. انقر ⟳ لاكتشاف الطابعات.',
'QZ_Not_Running' => 'QZ Tray غير مشغّل على هذا الحاسوب. ثبّته من qz.io وأبقه قيد التشغيل، ثم اسمح لهذا الموقع عندما يطلب QZ ذلك.',
'Detect_Printers' => 'اكتشاف الطابعات',
'QZ_Download_Cert' => 'تنزيل الشهادة (override.crt)',
'QZ_Setup_Title' => 'كيفية إعداد الطباعة عبر QZ Tray (مرة واحدة، على كل حاسوب يطبع الملصقات)',
'QZ_Step_Install' => '1. ثبّت QZ Tray على هذا الحاسوب — نزّله مجانًا من qz.io، ثم شغّله واتركه يعمل (يظهر في شريط النظام على ويندوز أو في شريط القوائم على macOS).',
'QZ_Step_Connect' => '2. وصّل طابعة الملصقات عبر USB وتأكد من أنها مثبتة في نظام التشغيل (ويندوز: الإعدادات > الطابعات والماسحات — macOS: إعدادات النظام > Printers & Scanners).',
'QZ_Step_Detect' => '3. انقر زر ⟳ بجانب "اسم الطابعة" أعلاه لاكتشاف الطابعات على هذا الحاسوب، ثم اختر طابعة الملصقات. اترك الحقل فارغًا لاستخدام الطابعة الافتراضية للحاسوب.',
'QZ_Step_Cert' => '4. للطباعة دون نافذة طلب الإذن، نزّل الشهادة أدناه وانسخها إلى مجلد تثبيت QZ Tray بعد إعادة تسميتها إلى override.crt (ويندوز: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — لينكس: /opt/qz-tray). ثم أغلق QZ Tray وشغّله من جديد.',
'QZ_Step_Test' => '5. انقر "طباعة ملصق تجريبي" أدناه. إذا طلب QZ Tray الإذن، انقر Allow — ومع تثبيت الشهادة لن يطلبه مرة أخرى.',
'QZ_Step_Save' => '6. انقر "إرسال" لحفظ هذه الإعدادات. ستُطبع الملصقات من صفحة طباعة الباركود مباشرة على هذه الطابعة، دون نافذة طباعة المتصفح.',
'QZ_Setup_Note' => 'يعمل QZ Tray على الحاسوب الذي تتصفح منه، لذلك يعمل هذا حتى عندما يكون Stocky مستضافًا على خادم بعيد. كل حاسوب يطبع الملصقات يحتاج إلى تثبيت QZ Tray.',

