'VG_Opt_Step7' => 'يتم إنشاء الرموز تلقائيًا. اكتب رمزك الخاص أو انقر على أيقونة التحديث لإنشاء رمز آخر.',
'VG_Opt_Step8' => 'اختياري: حدد "عينات الألوان" على أحد الخيارات واختر لونًا لكل قيمة؛ يعرضه المتجر كنقطة ملونة.',
'VG_Rows_Title' => 'صفوف المتغيرات',
'VG_Rows_Text' => 'يحتوي كل صف على صورة ورمز وباركود وتكلفة وسعر وسعر جملة وأدنى سعر بيع. عند إنشاء منتج يمكنك أيضًا إدخال المخزون الافتتاحي لكل مستودع لكل متغير. تعني علامة "غير مكتمل" أن الصف يفتقد قيمة لأحد الخيارات.',
'VG_List_Title' => 'وضع القائمة البسيطة',
'VG_List_Text' => 'اكتب اسم المتغير واضغط Enter (أو انقر على إضافة) لإلحاق صف، ثم املأ رمزه وأسعاره. هذا هو السلوك التقليدي ويظل متاحًا للمنتجات الحالية.',
'VG_Edit_Title' => 'التعديل لاحقًا',
'VG_Edit_1' => 'أضف قيمة وانقر على "إنشاء المتغيرات": تُضاف التوليفات الناقصة فقط. تحتفظ الصفوف الحالية برموزها وأسعارها وسجلها.',
'VG_Edit_2' => 'تؤدي إزالة قيمة أو خيار إلى إزالة الصفوف التي تستخدمه. تُحذف الصفوف المحفوظة مسبقًا عند حفظ المنتج، بعد التأكيد.',
'VG_Edit_3' => 'لا يمكن إزالة متغير لا يزال لديه مخزون. قم بتسوية مخزونه أو تحويله أولًا.',
'VG_Edit_4' => 'يؤدي الانتقال إلى "قائمة بسيطة" إلى الاحتفاظ بالصفوف وأسمائها مع حذف تعريفات الخيارات.',
'VG_Store_Title' => 'في المتجر الإلكتروني',
'VG_Store_Text' => 'يختار العملاء قيمة واحدة لكل خيار، مثل اللون ثم المقاس. تُعطَّل التوليفات غير الموجودة ويُشطب على غير المتوفرة في المخزون. المتغير المختار هو ما يُضاف إلى السلة.',
