'Upd_Guide_Before_No_Manual' => '{not} تحتاج إلى إنشاء نسخة احتياطية يدويًا أو فك ضغط الملفات أو تشغيل أوامر أو تعديل ملفات الإعدادات أو المساس بقاعدة البيانات — يقوم المُحدِّث بكل ذلك تلقائيًا. (وبالطبع، لا ضرر من نسخة احتياطية يدوية إضافية.)',
