'Upd_Guide_Running_Title' => '2. تشغيل التحديث',
'Upd_Guide_Run_Open' => 'افتح {path} (هذه الصفحة) وابقَ في تبويب {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: انقر أو اسحب الحزمة التي نزّلتها إلى مربع الرفع. تُرفع الملفات الكبيرة على أجزاء صغيرة، لذا يعمل هذا أيضًا على الاستضافة المشتركة ذات حدود الرفع المنخفضة. ويحمي مجموع اختباري (checksum) من الرفع التالف أو غير المكتمل.',
'Upd_Upload_The_Zip' => 'ارفع ملف ZIP',
'Upd_Guide_Run_Validation' => '{auto} بعد الرفع (ويمكنك إعادة تشغيله بالزر {button}). يتحقق النظام من: سلامة ملف ZIP، وبنية الحزمة واكتمالها، وتوافق الإصدار (يُرفض الرجوع إلى إصدار أقدم)، وإصدار PHP والإضافات المطلوبة، وصلاحيات الملفات، والمساحة الحرة على القرص، والاتصال بقاعدة البيانات، والإعدادات، وعدم وجود تحديث آخر قيد التشغيل.',
'Upd_Validation_Runs_Automatically' => 'يتم التحقق تلقائيًا',
'Upd_Guide_Run_Review' => 'راجع لوحة {panel}. لا يظهر الزر {button} إلا عند نجاح جميع الفحوصات الحرجة. وإذا فشل أحد الفحوصات، تخبرك الرسالة بالضبط بما يجب إصلاحه.',
'Upd_Guide_Run_Click' => 'انقر على {button} وقم بالتأكيد. ثم {keep} وتابع شريط التقدم. ينفّذ النظام بالترتيب:',
'Upd_Keep_Page_Open' => 'أبقِ هذه الصفحة مفتوحة',
'Upd_Guide_Phase_Backup' => '{label} — يتم إنشاء نسخة كاملة من قاعدة البيانات، وملف ZIP لكل ملفات التطبيق التي قد يغيّرها التحديث، ونسخة من {env}، ثم {verified}. لا يمس التحديث أبدًا ملفاتك المرفوعة ({images}) ولا {storage}، لذا لا تتم أرشفتها. وإذا تعذّر إنشاء النسخة الاحتياطية، يتوقف التحديث هنا دون تغيير أي شيء.',
'Upd_Verified' => 'يتم التحقق منها',
'Upd_Guide_Phase_Prepare' => '{label} — يُستخرج الإصدار الجديد إلى منطقة تجهيز ويُتحقق منه مرة أخرى. يبقى التطبيق المباشر دون أي تغيير.',
'Upd_Guide_Phase_Maintenance' => '{label} — يتم تفعيل وضع الصيانة؛ ويرى الزوار شاشة ودية تقول "سنعود قريبًا".',
'Upd_Guide_Phase_Files' => '{label} — تُستبدل الملفات الجديدة بشكل شبه فوري؛ وتُحفظ الملفات القديمة جانبًا للتراجع. لا تُستبدل المسارات المحمية ({env} و{storage} و{images}) أبدًا.',
'Upd_Guide_Phase_Database' => '{label} — تُنفَّذ عمليات الترحيل (migrations)، ثم تُحدَّث الصلاحيات والترجمات والقوالب.',
'Upd_Guide_Phase_Cache' => '{label} — تُمسح جميع ذاكرات التخزين المؤقت ويُعاد بناؤها.',
'Upd_Guide_Phase_Verify' => '{label} — تؤكد فحوصات السلامة أن الإصدار الجديد يعمل، وأن قاعدة البيانات تعمل، وأن جميع عمليات الترحيل نُفّذت، وأن الإعدادات صالحة.',
'Upd_Guide_Phase_Done' => '{label} — يُلغى وضع الصيانة وتُحذف الملفات المؤقتة.',
'Upd_Guide_Run_Success' => 'عندما ترى {success}، انقر على {reload} وحدّث المتصفح تحديثًا كاملًا ({keys}) لتحميل ملفات لوحة الإدارة الجديدة.',
'Upd_Update_Successful_Short' => 'تم التحديث بنجاح',
'Upd_Guide_No_Internet' => 'لا حاجة إلى اتصال بالإنترنت أثناء التحديث — فكل شيء يأتي من ملف ZIP المرفوع. وانقطاع الاتصال أو إغلاق المتصفح لا يُفسد التحديث: إذ يتذكر الخادم بالضبط أين توقف.',
'Upd_Guide_Wrong_Title' => '3. إذا حدث خطأ ما',
'Upd_Guide_Wrong_Rollback' => '{label} — إذا فشل أي شيء بعد بدء تغيير الملفات (خطأ في الاستخراج، فشل في الترحيل، فشل في فحص السلامة، امتلاء القرص، …)، يستعيد النظام تلقائيًا الملفات السابقة وقاعدة البيانات من النسخة الاحتياطية المُتحقق منها، ويُلغي وضع الصيانة، ويعرض {message}. وتعود تمامًا إلى حيث بدأت.',
'Upd_Automatic_Rollback' => 'التراجع التلقائي',
'Upd_Failed_Previous_Restored' => 'فشل التحديث — تمت استعادة الإصدار السابق',
'Upd_Guide_Wrong_Interrupted' => '{label} (إعادة تشغيل الخادم، انتهاء المهلة، إغلاق المتصفح، انقطاع الكهرباء) — عند إعادة فتح هذه الصفحة، يعرض شريط أحمر خيارين آمنين: {resume} (يستأنف من الخطوة نفسها التي توقف عندها) أو {rollback} (يستعيد الإصدار السابق من النسخة الاحتياطية).',
'Upd_Interrupted_Update' => 'تحديث متقطع',
'Upd_Guide_Wrong_Unreachable' => '{label} — استخدم {console} المستقلة على {path}. فهي تعمل حتى أثناء وجود الموقع في وضع الصيانة أو تعطل ملفات لوحة الإدارة، وتوفر إجراءَي المتابعة / التراجع نفسيهما. كما يوجد رابط غير بارز "دخول المسؤول" أسفل شاشة الصيانة.',
'Upd_Admin_Unreachable' => 'تعذّر الوصول إلى لوحة الإدارة',
'Upd_Recovery_Console' => 'وحدة الاسترداد',
'Upd_Guide_Wrong_Locked_Out' => '{label} — أثناء تشغيل التحديث، تعرض هذه الصفحة {link}. احفظه إذا احتجت إلى العودة (مثلًا بعد انتهاء جلستك)؛ فهو يتيح لك تجاوز شاشة الصيانة لتسجيل الدخول مجددًا.',
'Upd_Locked_Out_Maintenance' => 'تم منع الدخول بسبب وضع الصيانة',
'Upd_Bypass_Link' => 'رابط التجاوز',
'Upd_Guide_Wrong_Concurrent' => '{label} — سيرى {message} لا يمكن تشغيل أكثر من تحديث واحد في الوقت نفسه.',
'Upd_Another_Admin_Updating' => 'مسؤول آخر يحاول التحديث في الوقت نفسه',
'Upd_Guide_Backups_Title' => '4. النسخ الاحتياطية والاستعادة',
'Upd_Guide_Backups_Created' => 'ينشئ كل تحديث نسخة احتياطية {before} المساس بأي شيء: جميع ملفات التطبيق التي قد يستبدلها التحديث، ونسخة من {env}، ونسخة كاملة من قاعدة البيانات. لا يعدّل التحديث أبدًا الملفات المرفوعة ولا {storage}، لذا فهي ليست جزءًا منها — احتفظ بنسخك الاحتياطية الخاصة لها. تُحفظ النسخ الاحتياطية في {path} ولا يمكن الوصول إليها أبدًا من الويب.',
'Upd_Before' => 'قبل',
'Upd_Guide_Backups_Panel' => 'تعرضها لوحة {panel} في تبويب {tab} مع التاريخ والإصدار والحجم. ومن هناك يمكنك {restore} أي نسخة احتياطية كاملة (الملفات + قاعدة البيانات — مع أخذ نسخة أمان من قاعدة البيانات الحالية أولًا) أو {delete} النسخ القديمة.',
'Upd_Restore_Verb' => 'استعادة',
'Upd_Delete_Verb' => 'حذف',
'Upd_Guide_Backups_Retention' => 'استخدم {keep} لاختيار عدد النسخ الاحتياطية المحفوظة؛ وتُحذف النسخ الأقدم تلقائيًا بعد كل تحديث ناجح. لا يمكن أبدًا حذف آخر نسخة احتياطية كاملة متبقية — لتبقى لديك دائمًا طريقة للعودة.',
'Upd_Guide_Manual_Title' => '5. التحديث اليدوي (الطريقة البديلة)',
'Upd_Guide_Manual_Text' => 'إذا كنت تفضّل التحديث يدويًا، أو تعذّر استخدام أداة الرفع على خادمك، فاتبع التعليمات خطوة بخطوة في تبويب {tab} في هذه الصفحة.',
'Upd_Guide_Clear_Cache_First' => 'إذا ظهرت الصفحات معطوبة أو فارغة بعد أي تحديث، فامسح ذاكرة التخزين المؤقت للمتصفح أولًا — فهي السبب في أغلب الأحيان.',
'Upd_Restore_Backup_Confirm' => 'استعادة هذه النسخة الاحتياطية؟ سيتم استبدال الملفات الحالية وقاعدة البيانات الحالية بالنسخة الاحتياطية. تُؤخذ نسخة أمان من قاعدة البيانات الحالية أولًا. (v{version} — {date})',
'Woo_Guide_Lead' => 'كيف يبقى متجر WooCommerce متزامنًا مع نظام ERP. أسطر cron أدناه مُعدّة لهذا الخادم، لذا يمكن نسخها إليه مباشرة.',
'Woo_Guide_Ways_Note' => 'على عكس Shopify، لا يرسل WooCommerce أي شيء إلى نظام ERP من تلقاء نفسه — لا يوجد مستقبِل Webhook هنا، لذا فكل ما يأتي {in} يصل وفق الجدول الزمني. فقط المخزون {out} يمكن أن يكون فوريًا.',
'Woo_In' => 'واردًا',
'Woo_Out' => 'الصادر',
'Woo_Guide_Both_Ways_Title' => 'كلا الاتجاهين يحتاجان إلى هذا أولًا',
'Woo_Api_Keys' => 'مفاتيح API',
'Woo_Guide_Api_Keys_Text' => '{path}، الصلاحية {perm}. انسخ مفتاح المستهلك (consumer key) والسر (secret) إلى تبويب {settings}، مع رابط المتجر — عنوان موقعك بدون شرطة مائلة في النهاية، مثل {example}.',
'Woo_Credentials_Saved' => 'تم حفظ بيانات الاعتماد',
'Woo_Not_Configured_Yet' => 'لم تتم التهيئة بعد',
'Woo_Guide_Wp_App_Password_Title' => 'كلمة مرور تطبيق WordPress (اختياري)',
'Woo_Guide_Wp_App_Password_Text' => 'تُستخدم لصور المنتجات فقط. تنقل واجهة WooCommerce API المنتجات والمخزون والفئات والعلامات التجارية والعملاء والطلبات؛ أما واجهة WordPress API فهي التي تبحث في مكتبة الوسائط وترفع الصورة غير الموجودة بعد.',
'Woo_Guide_Wp_App_Password_Note' => 'استخدم مستخدم WordPress يمكنه إدارة الوسائط، وأنشئ كلمة المرور من {path}. اترك الحقلين فارغين وستتم مزامنة كل شيء — فقط إرفاق الصور هو ما يتم تخطيه.',
'Woo_Guide_Pick_Way_Title' => 'ثم اختر طريقة المزامنة',
'Woo_Right_Away' => 'فورًا',
'Woo_Stock_Live' => 'المخزون مباشر',
'Woo_Stock_Not_Live' => 'المخزون غير مباشر',
'Woo_Guide_Realtime_Lead' => 'اتجاه واحد فقط: المخزون والمنتجات الصادرة من نظام ERP. أما الطلبات وتعديلات المنتجات التي تتم في WooCommerce فتصل وفق الجدول الزمني — راجع التبويب الآخر.',
'Woo_Push_Stock_On_Change' => 'إرسال المخزون فور تغيّره',
'Woo_Setting_People_Miss' => 'هذا هو الإعداد الذي يغفل عنه الكثيرون',
'Woo_Guide_Pos_Sale_Not_Reach' => 'بيع نقطة البيع {not} إلى WooCommerce من تلقاء نفسه. إذا تُرك معطّلًا، فلن يعلم المتجر إلا عند مزامنة المخزون التالية — كل ساعة افتراضيًا — وفي تلك الفترة قد يبيع وحدة سبق أن بعتها عند الصندوق.',
'Woo_Does_Not' => 'لا يصل',
'Woo_Guide_Tick_Instant' => 'فعّل {option} في تبويب {settings}. هذا كل ما في الإعداد — بدون عامل طابور، وبدون cron. بعدها، كل عملية بيع ومرتجع وتسوية وتحويل وشراء مستلَم ترسل تحديثًا لتلك المنتجات فقط، مباشرة بعد حفظ العملية، وعملية بيع من عشرين سطرًا تكلّف إرسالًا واحدًا لا عشرين. ولا ينتظر الصندوق ذلك أبدًا.',
'Woo_Currently' => 'حاليًا:',
'Woo_Instant_On_Text' => 'مفعّل — يُرسل المخزون عند التغيير',
'Woo_Instant_Off_Text' => 'معطّل — المخزون وفق الجدول الزمني فقط',
'Woo_Guide_Instant_Note' => 'لا تُرسل إلا المنتجات المرتبطة مسبقًا بـ WooCommerce — فالمنتج الذي لم تتم مزامنته قط ليس له ما يُصحَّح في المتجر. تمر المنتجات المتغيرة عبر المنتج الأصل، ويُعاد إرسال المنتج المجمّع (combo) عند تحرك أي من مكوناته. العمليات الجماعية (حذف منتج، إعادة تعيين مستودع) تكتب المخزون دون إطلاق حدث، وهذا أحد أسباب الإبقاء على مزامنة المخزون كل ساعة أيضًا.',
'Woo_Push_Products_On_Save' => 'إرسال المنتجات فور حفظها',
'Woo_Guide_Tick_Auto_Products' => 'فعّل {option} في تبويب {settings}، وسيُرسل أي منتج يُنشأ أو يُعدّل أو يُكرّر في Stocky إلى WooCommerce مباشرة بعد حفظه — التفاصيل والسعر والمتغيرات والصور، ثم مخزونه. ويُنشأ المنتج الجديد في المتجر فورًا بدلًا من انتظار مزامنة المنتجات الليلية.',
'Woo_On' => 'مفعّل',
'Woo_Off' => 'معطّل',
'Woo_Guide_Bulk_Imports_Note' => 'لا تُرسل عمليات الاستيراد الجماعية منتجًا تلو الآخر — شغّل مزامنة المنتجات بعد الاستيراد. زامن الفئات والعلامات التجارية أولًا، ليصل المنتج المُرسل إلى الفئة الصحيحة.',
'Woo_Nothing_Else_To_Install' => 'لا شيء آخر لتثبيته',
'Woo_Guide_Same_Process' => 'بدون عامل طابور، وبدون إدخال cron. يعمل الإرسال في العملية نفسها التي خدمت البيع، {after} إرسال الاستجابة، لذا لا ينتظر الصندوق WooCommerce أبدًا. ولا تتداخل عمليات الإرسال: التغييرات التي تتم أثناء تشغيل إحداها تنتظرها وتُرسل بعدها مباشرة.',
'Woo_After' => 'بعد',
'Woo_Guide_Shop_Stops_Answering' => 'يتم التخلي عن المتجر الذي يتوقف عن الاستجابة بعد ثماني ثوانٍ، وتتوقف عمليات الإرسال مؤقتًا لمدة خمس دقائق حتى لا تنتظره كل عملية بيع مجددًا؛ وتُرسل التغييرات التي وصلت في الأثناء مع أول إرسال بعد التوقف، وتلحق مزامنة المخزون كل ساعة بالركب في جميع الأحوال. ويُسجَّل كل توقف في تبويب السجلات.',
'Woo_Guide_Artisan_Exception' => 'استثناء واحد: تغيير المخزون الذي يتم عبر أمر artisan ليس له استجابة يأتي بعدها، لذا يوضع في الطابور {queue} بدلًا من ذلك. لكي تُرسل هذه التغييرات بسرعة أيضًا، قم بتفريغ ذلك الطابور:',
