'Presta_Push_Products_Desc' => 'ينشئ المنتجات البسيطة المفقودة على PrestaShop (مع مخزونها الحالي). يتم تخطي المنتجات المرتبطة مسبقًا والمنتجات ذات المتغيرات — واصل تعديل تفاصيل المنتجات في PrestaShop، أو اسحبها لتحديث النسخة المحلية.',
'Presta_Pull_Products_Desc' => 'يستورد منتجات PrestaShop، مطابقًا المنتجات الموجودة حسب المرجع (SKU) ومنشئًا البقية. تُستورد التوليفات (Combinations) كمنتجها الأصل.',
