'Shopify_Hook_Note_Register' => 'يؤدي التسجيل إلى إنشاء الاشتراكات في Shopify وتوجيهها إلى هذا العنوان تلقائيًا. لا تضفه يدويًا من Shopify ← Settings ← Notifications ← Webhooks: فتلك موقّعة بسر مختلف وسيتم رفض كل عملية تسليم.',
'Shopify_Hook_Verified_Client' => 'يتم التحقق من عمليات التسليم باستخدام Client secret الخاص بالتطبيق، وهو محفوظ مسبقًا.',
'Shopify_Hook_Signature_Required' => 'تُرفض عمليات التسليم التي لا تحمل توقيعًا صالحًا، لذا يجب تعيين السر قبل أن تعمل الـ Webhooks.',
'Shopify_Hook_Retries' => 'يعيد Shopify المحاولة حتى يتلقى استجابة 2xx، ويُسجَّل كل تسليم مرة واحدة — الحدث المكرر لا يُحدث أي أثر، ولا ينشئ طلبًا مكررًا.',
'Shopify_No_Signing_Secret' => 'لا يوجد سر توقيع محفوظ',
