'Shopify_G_Lead_Store' => 'ما يحتاجه هذا المتجر ليبقى متزامنًا. كل ما هنا خاص بهذا المتجر — المسارات والمعرّفات حقيقية، لذا يمكن نسخ الأوامر مباشرة إلى الخادم.',
'Shopify_G_Lead_Generic' => 'كيف يبقى متجر Shopify متزامنًا مع ERP. اختر متجرًا أعلاه لرؤية حالته، أو اقرأه كما هو — سطر cron ورابط الـ Webhook متطابقان أيًّا كان المتجر الذي تربطه.',
'Shopify_G_Ways_Note' => 'تستخدم معظم المتاجر الطريقتين معًا: الأولى تُبقي المتجر محدّثًا دقيقة بدقيقة، والثانية تلتقط ما فات الأولى — Webhook لم يصل أبدًا، أو تعديل أُجري مباشرة في لوحة إدارة Shopify، أو ليلة كان فيها الموقع متوقفًا.',
'Shopify_G_Both_Need' => 'كلتا الطريقتين تحتاجان هذا أولًا',
'Shopify_G_Credentials' => 'بيانات اعتماد Shopify',
'Shopify_G_Cred_Intro' => 'منذ يناير 2026 لم يعد Shopify ينشئ تطبيقات مخصصة داخل لوحة الإدارة، لذا هناك نوعان من الاتصال:',
'Shopify_G_Cred_DevDash' => '{app} (أي متجر يُربط الآن) — {path}. امنح نطاقات Admin API لما يزامنه هذا المتجر، وثبّت التطبيق على المتجر، ثم انسخ {clientId} و{clientSecret} من صفحة إعدادات التطبيق إلى {where}. يستبدلهما ERP برمز وصول بنفسه ويجدده قبل انتهاء صلاحيته كل 24 ساعة. يوقّع Client secret أيضًا الـ Webhooks، لذا لا حاجة لأي شيء آخر. يجب أن يكون التطبيق والمتجر ضمن نفس مؤسسة Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'تطبيق Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (أُنشئ في لوحة الإدارة قبل 2026) — يستمر في العمل دون تغيير باستخدام {token} ({prefix}) و{secret} كسر توقيع الـ Webhook. هذه القيمة ليست نفس الرمز، والخلط بينهما هو السبب المعتاد لرفض الـ Webhooks.',
'Shopify_G_Legacy_App' => 'تطبيق مخصص قديم',
'Shopify_G_API_Secret_Key' => 'مفتاح API السري',
'Shopify_G_Stored' => 'محفوظ',
'Shopify_G_Missing_Refused' => 'مفقود — سيتم رفض عمليات التسليم',
'Shopify_G_Where_Data_Desc' => '{path} مستودع ERP الذي يبيع هذا المتجر مخزونه، وموقع Shopify الذي يُكتب إليه ذلك المخزون. ترفض مزامنة المخزون واستيراد الطلبات العمل بدونهما.',
'Shopify_G_Currently' => 'حاليًا: المستودع {warehouse}، الموقع {location}',
'Shopify_G_Not_Set_Lower' => 'غير معيّن',
'Shopify_G_Ready' => 'جاهز',
'Shopify_G_Incomplete' => 'غير مكتمل',
'Shopify_G_Manual_Syncs' => 'عمليات المزامنة التي تبدأها يدويًا',
'Shopify_G_Manual_Desc' => 'المزامنة التي تبدأ من {centre} تستجيب فورًا وتعمل في الخلفية، على شرائح قصيرة تكمل كل منها من حيث توقفت سابقتها. لا يُقطع الكتالوج الكبير أبدًا في منتصفه بسبب استضافة تُنهي طلبات الويب الطويلة (LiteSpeed، nginx، موازن الأحمال)، وإغلاق الصفحة لا يوقفها. العامل المسؤول عن ذلك هو سطر cron إضافي:',
'Shopify_G_Cron_Copied' => 'تم نسخ سطر cron',
'Shopify_G_Manual_Note' => 'بدونه تكتمل المزامنة أيضًا، ولكن فقط طالما بقيت صفحة مركز المزامنة مفتوحة: عندما لا يلتقط أي عامل التشغيل خلال بضع ثوانٍ، تكمله الصفحة بنفسها، طلبًا قصيرًا تلو الآخر. على Windows استخدم Task Scheduler كل دقيقة: البرنامج {program}، الوسائط {args}، يبدأ في {dir}.',
'Shopify_G_Then_Pick' => 'ثم اختر طريقة بقائه متزامنًا',
'Shopify_G_Right_Away' => 'فورًا',
'Shopify_G_Stock_Live' => 'المخزون مباشر',
'Shopify_G_Stock_Not_Live' => 'المخزون غير مباشر',
'Shopify_G_Realtime_Lead' => 'يُرسَل كل تغيير لحظة حدوثه، خلال ثوانٍ. هناك نصفان، وكل منهما بمفتاح منفصل: {webhooks} تجلب أحداث المتجر إلى الداخل، و{push} يرسل المخزون إلى الخارج.',
'Shopify_G_Webhooks_Lower' => 'الـ Webhooks',
'Shopify_G_Instant_Push_Lower' => 'الدفع الفوري للمخزون',
'Shopify_G_Webhooks_In' => 'الـ Webhooks — المتجر → ERP',
'Shopify_G_Webhooks_Desc' => 'الطلبات وتغييرات حالة الطلبات وتعديلات المنتجات والعملاء والمخزون التي تتم في Shopify. افتح المتجر واضغط {button} في {tab} — الضغط مرتين آمن. يرسل Shopify إلى:',
'Shopify_G_Webhooks_Tab' => 'علامة تبويب Webhooks',
'Shopify_G_Webhooks_Note' => 'يجب أن يكون العنوان قابلًا للوصول من الإنترنت عبر HTTPS — لن يرسل Shopify إلى {localhost} أو نطاق {test}. يُسجَّل كل تسليم مرة واحدة، لذا لا يمكن لإعادة محاولات Shopify إنشاء طلب مكرر، ويمكن إعادة تشغيل التسليم الفاشل. تُرفض عمليات التسليم حتى يُحفظ سر التوقيع من الخطوة 1.',
'Shopify_G_Instant_Out' => 'الدفع الفوري للمخزون — ERP → المتجر',
'Shopify_G_Setting_Missed' => 'هذا هو الإعداد الذي يغفل عنه الناس',
'Shopify_G_Pos_Not_Auto' => 'عملية بيع نقطة البيع {not} تصل إلى Shopify من تلقاء نفسها. إذا تُرك معطّلًا، لا يعلم المتجر بها إلا عند خطوة دفع المخزون التالية — وفي تلك الفترة قد يبيع وحدة سبق أن بعتها عند الصندوق.',
'Shopify_G_Not' => 'لا',
'Shopify_G_Tick_Push' => 'فعّل {setting} في {where}. هذا هو الإعداد بالكامل — لا عامل ولا cron. بعدها، كل عملية بيع ومرتجع وتسوية ترسل دفعًا لتلك المنتجات فقط، مباشرة بعد حفظ البيع، وعملية بيع من عشرين سطرًا تكلّف دفعًا واحدًا لا عشرين. لا ينتظره الصندوق أبدًا.',
'Shopify_G_This_Store' => 'هذا المتجر:',
'Shopify_G_Push_On' => 'مفعّل — يُدفع المخزون عند التغيير',
'Shopify_G_Push_Off' => 'معطّل — المخزون وفق الجدول فقط',
'Shopify_G_Push_Note' => 'تُدفع فقط المنتجات التي لديها ربط مع Shopify، وفقط الحركات في مستودع هذا المتجر. العمليات الجماعية — حذف منتج، أو إعادة تعيين مستودع — تكتب المخزون دون إطلاق حدث، وهذا أحد أسباب الإبقاء على خطوة المخزون المجدولة أيضًا.',
'Shopify_G_Nothing_Install' => 'لا شيء آخر للتثبيت',
'Shopify_G_No_Worker_Note' => 'لا يحتاج أي من النصفين إلى عامل قائمة انتظار أو إدخال cron. يُعالَج الـ Webhook الوارد ضمن الطلب الذي يرسله Shopify؛ ويعمل دفع المخزون الصادر في نفس العملية التي خدمت عملية البيع، {after} إرسال الاستجابة — لذا لا ينتظر الصندوق Shopify أبدًا، والمتجر الذي يتوقف عن الاستجابة يُتخلّى عنه بعد عشر ثوانٍ ويُترك لدفع المخزون المجدول التالي.',
'Shopify_G_After' => 'بعد',
'Shopify_G_Artisan_Note' => 'استثناء واحد: تغيير المخزون الذي يتم بواسطة أمر artisan ليس له استجابة يأتي بعدها، لذا يوضع في قائمة الانتظار {queue} بدلًا من ذلك. إذا أردت إرسال هذه التغييرات بسرعة أيضًا، فقم بتفريغ قائمة الانتظار تلك:',
'Shopify_G_On_Schedule' => 'وفق جدول',
'Shopify_G_On_Lower' => 'مفعّل',
'Shopify_G_Off_Lower' => 'معطّل',
'Shopify_G_Scheduled_Lead' => 'يُعاد فحص كل شيء بين حين وآخر، في كلا الاتجاهين. أبطأ من الوقت الفعلي، لكنه ما يدفع المخزون في المتاجر التي لا تستخدم الدفع الفوري، وما يلتقط الـ Webhook الفائت، والطريقة الوحيدة لنقل كتالوج كامل.',
'Shopify_G_Cron_Entry' => 'إدخال cron',
'Shopify_G_Cron_Entry_Desc' => 'لا يعمل أي شيء مجدول بدونه. سطر واحد، لهذه الوحدة فقط — أضفه بجانب أي شيء آخر اخترت جدولته:',
'Shopify_G_Cron_Note' => 'كل خمس دقائق هي أدق دقة يمكن للخطة استخدامها، لأن خمس دقائق هي أقصر فاصل للخطوة. الإدخال الأقل تكرارًا يصبح ببساطة الحد الأدنى — مع {example}، تعمل الخطوة المضبوطة على 5 دقائق كل 15 دقيقة. على Windows استخدم Task Scheduler: البرنامج {program}، الوسائط {args}، يبدأ في {dir}.',
'Shopify_G_Switch_On_Plan' => 'فعّله، واختر الخطة',
'Shopify_G_Plan_Desc' => '{where} يحدد المفتاح ما إذا كان يُسمح لـ cron بالعمل أصلًا؛ وتحدد الخطة ما يفعله. الـ{step} هي كيان واحد في اتجاه واحد بفاصل خاص بها — {first}، {second}. يُستخدم الفاصل الافتراضي لأي خطوة تترك حقلها فارغًا.',
'Shopify_G_Step_Lower' => 'خطوة',
'Shopify_G_Plan_Note' => 'اترك الخطة فارغة وسيسحب المتجر الطلبات ويدفع المخزون بالفاصل الافتراضي، وهو ما تريده معظم المتاجر. الطلبات للسحب فقط: Shopify هو المكان الذي يقدّم فيه العميل طلبه.',
'Shopify_G_Schedule_On' => 'الجدولة مفعّلة',
'Shopify_G_Schedule_Off' => 'الجدولة معطّلة — يدوي فقط',
'Shopify_G_When_Step_Runs' => 'متى تعمل الخطوة فعليًا',
'Shopify_G_When_Note' => 'تكون الخطوة مستحقة عندما تكون آخر مرة {started} فيها نفس الخطوة أقدم من فاصلها، وفقًا لسجل التشغيل. لذا فإن المزامنة التي تبدأها يدويًا تؤجل المزامنة التلقائية التالية، والخطوة التي تستمر في الفشل يُعاد تشغيلها حسب فاصلها لا في كل نبضة. تعرض نظرة عامة المتجر آخر تشغيل لكل خطوة، وموعد الاستحقاق التالي، وسبب حظرها عند حدوث ذلك. شغّل أول دفع للكتالوج يدويًا — مع {dryRun} أولًا — قبل وضعه على جدول.',
'Shopify_G_Started_Lower' => 'بدأت',
'Shopify_G_Where_Setting' => 'أين يوجد كل إعداد',
'Shopify_G_Where_Setting_Note' => 'جميع هذه الإعدادات موجودة على متجر قائم: {path}، ثم القلم (أو {edit} في صفحة المتجر نفسه).',
'Shopify_G_Product_Images' => 'صور المنتجات',
'Shopify_G_Img_1' => 'تُرسَل الصور مع المنتج عند {push} — الصورة الرئيسية أولًا، ثم المعرض، ثم صورة لكل متغير له صورته الخاصة، بحد أقصى خمسين.',
'Shopify_G_Products_Push' => 'دفع المنتجات',
'Shopify_G_Img_2' => 'تُرفع صورة المتغير مع المنتج ثم {assigned}، وهذه هي طريقة Shopify في تمثيلها: يشير المتغير إلى إحدى صور المنتج. المتغير الذي يعيد استخدام الصورة الرئيسية لا يرفعها مرتين.',
'Shopify_G_Assigned' => 'تُعيَّن لذلك المتغير',
'Shopify_G_Img_3' => 'الصورة المخزنة كملف يتم {uploaded} إلى Shopify، لا ربطها، لذا تعمل حتى عندما يتعذر الوصول إلى هذا التثبيت من الإنترنت. أما الصورة المضافة كرابط ملصوق فتُسلَّم إلى Shopify بهذا الرابط، الذي يجب أن يكون متاحًا للعامة.',
'Shopify_G_Uploaded' => 'رفعها',
'Shopify_G_Img_4' => 'لا يُعاد إرسالها إلا عند تغيّرها فعلًا — الدفع الذي يغيّر السعر فقط لا يمس صور المتجر، لأن إرسالها يستبدل المجموعة بأكملها.',
'Shopify_G_Img_5' => 'إزالة صورة في ERP {not} تحذفها في Shopify. احذفها هناك أيضًا، وإلا سيستمر المتجر في عرضها.',
'Shopify_G_Commands' => 'أوامر تستحق المعرفة',
'Shopify_G_Command_Copied' => 'تم نسخ الأمر',
'Shopify_G_Foot' => 'كل مزامنة تكتب إلى {logs}، وتعرض نظرة عامة كل متجر متى عملت كل خطوة آخر مرة، ومتى تستحق التالية، وما الذي يعيقها عند وجود عائق. هذا هو المكان الذي تبحث فيه أولًا عندما لا تفعل المزامنة ما توقعته.',
'Shopify_G_Covers' => 'يغطي',
'Shopify_G_Covers_Rt' => 'الطلبات والتعديلات التي تتم في Shopify؛ والمخزون الخارج من ERP (بيع نقطة البيع، مرتجع، تسوية)',
'Shopify_G_Covers_Sch' => 'كل شيء، في كلا الاتجاهين — بما في ذلك دفع الكتالوج وأي شيء فات المسار السريع',
