'Cr_Guide_B_Booking' => 'يملأ خيار إرسال إلى شركة الشحن النموذج من بيانات عملية البيع: المستلم، والعنوان، والمبلغ المستحق المتبقي كدفع عند الاستلام، ووزن المنتجات. تعرض شركات الشحن التي لديها قوائم مدن خاصة بها أداة اختيار، ويتم تذكر اختيارك لتلك المدينة. توفر المنصات المجمِّعة وDHL وFedEx وUPS وLalamove خيار مقارنة الأسعار: اختر سعرًا ثم يقوم زر الحجز بشرائه. يمكن حجز عدة مبيعات دفعة واحدة من قائمة المبيعات.',
'Cr_Guide_T_Cod' => 'الدفع عند الاستلام',
'Cr_Guide_B_Cod' => 'ينتقل طرد الدفع عند الاستلام من غير محصَّل إلى محصَّل لدى شركة الشحن (عند التسليم) ثم إلى مدفوع لك. شركات الشحن التي تُبلغ عن الدفعات تنقل الخطوة الأخيرة بنفسها؛ أما الأخرى فاستخدم تحديث الدفع عند الاستلام. عند اختيار حساب في إعدادات شركات الشحن، تُسجَّل الدفعة كدفعة على عملية البيع. يمكن حفظ رسوم شركة الشحن كمصروف بعد اكتمال الطرد.',
'Cr_Guide_T_Returns' => 'الطرود المرتجعة',
'Cr_Guide_B_Returns' => 'افتراضيًا، ينتظر الطرد المرتجع في شحنات شركات الشحن ضمن المرتجعات للمراجعة. يُنشئ خيار إعادة التخزين مرتجع مبيعات للطلب بالكامل ويعيد الأصناف إلى المخزون؛ أما خيار التجاهل فلا يعيد شيئًا، وهو مخصص للطرود التالفة أو المفقودة. ويمكن ضبط إعدادات شركات الشحن لإعادة التخزين تلقائيًا بدلًا من ذلك.',
'Cr_Guide_T_Customers' => 'رسائل العملاء وصفحة التتبع',
'Cr_Guide_B_Customers' => 'ترسل إشعارات العملاء في إعدادات شركات الشحن رسائل SMS أو بريدًا إلكترونيًا أو WhatsApp عند الحالات التي تحددها، مرة واحدة لكل طرد، وبنصك الخاص. تتيح صفحة التتبع في متجرك الإلكتروني للعملاء متابعة الطرد برقم التتبع، أو برقم الطلب ورقم الهاتف. يحصل العملاء الذين يرجعون الطرود كثيرًا على شارة خطر الإرجاع عند الحجز.',
'Cr_Guide_T_Labels' => 'الملصقات',
'Cr_Guide_B_Labels' => 'يعطيك خيار طباعة الملصق ملصق شركة الشحن الخاص عندما تصدره (ملف PDF أو رابط أو صورة)، وإلا فملصق Stocky يحتوي على باركود التتبع والمبلغ المطلوب تحصيله. اسمح بالنوافذ المنبثقة لهذا الموقع لتتمكن من الطباعة. تعطي DHL وFedEx وUPS ملصقها مرة واحدة فقط عند الحجز، ويحتفظ به Stocky لإعادة الطباعة.',
'Cr_Guide_T_Faq' => 'استكشاف الأخطاء وإصلاحها',
'Cr_Guide_Q_Test' => 'فشل اختبار الاتصال',
'Cr_Guide_A_Test' => 'تُستخدم مفاتيح الوضع التجريبي مع الوضع التجريبي والمفاتيح الحية مع الوضع الحي؛ وهي مختلفة. افتح سجلات شركات الشحن واقرأ رد شركة الشحن لمعرفة السبب الدقيق.',
'Cr_Guide_Q_City' => 'ترفض شركة الشحن المدينة أو العنوان',
'Cr_Guide_A_City' => 'اختر المدينة من قائمة مدن شركة الشحن في نموذج الحجز؛ فشركات الشحن لا تقبل إلا أسماءها الخاصة. كما تحتاج شركات الشحن التي تعمل بالعناوين البريدية إلى الولاية والرمز البريدي ورمز الدولة المكون من حرفين.',
'Cr_Guide_Q_Webhook' => 'الحالات لا تتغير تلقائيًا',
'Cr_Guide_A_Webhook' => 'بالنسبة لشركات الشحن التي ترسل التحديثات، تأكد من تسجيل رابط Webhook لدى شركة الشحن: تعرض سجلات شركات الشحن كل تحديث مستلم، أو سبب رفضه (مثل سر غير صحيح). أما شركات الشحن الأخرى فيتم التحقق منها وفق الجدول الزمني في إعدادات شركات الشحن، ويقوم خيار التحقق من الحالة الآن بالاستعلام فورًا.',
'Cr_Guide_Q_Stuck' => 'تظهر على الشحنة رسالة خطأ في التحقق من الحالة',
'Cr_Guide_A_Stuck' => 'رفضت شركة الشحن عمليات التحقق الأخيرة؛ والسبب مذكور في الشحنة وفي سجلات شركات الشحن. بعد تكرار الفشل، يتوقف التحقق التلقائي من الشحنة: أصلح السبب، ثم استخدم التحقق من الحالة الآن.',
'Cr_Guide_Q_Label' => 'لا يُفتح شيء عند طباعة الملصق',
'Cr_Guide_A_Label' => 'حظر متصفحك النافذة المنبثقة. اسمح بالنوافذ المنبثقة لهذا الموقع وحاول مرة أخرى.',
'Cr_Guide_Q_Cod' => 'لم تُسجَّل دفعة الدفع عند الاستلام على عملية البيع',
'Cr_Guide_A_Cod' => 'في إعدادات شركات الشحن، يحتاج الدفع عند الاستلام إلى تفعيل المفتاح واختيار حساب. بدون حساب، يتم فقط وضع علامة على الدفعات بأنها مدفوعة.',
