'Tfa_Codes_Save' => 'احفظ رموز الاسترداد هذه في مكان آمن. كل رمز يتيح لك تسجيل الدخول مرة واحدة إذا فقدت هاتفك. لن تُعرض مرة أخرى.',
'Tfa_Reset' => 'إعادة تعيين المصادقة الثنائية',
'Tfa_Reset_Title' => 'إعادة تعيين المصادقة الثنائية؟',
'Tfa_Reset_Help' => 'سيسجّل :name الدخول بكلمة المرور فقط، ويمكنه بعد ذلك إعداد تطبيق المصادقة مرة أخرى. لا تفعل ذلك إلا بعد التأكد من هوية مقدم الطلب.',
'Tfa_Guide_Lead' => 'تضيف المصادقة الثنائية (2FA) خطوة ثانية لتسجيل الدخول: بعد كلمة المرور، يكتب الموظفون رمزًا من 6 أرقام من تطبيق مصادقة على هواتفهم. لم تعد كلمة المرور المسروقة أو المخمّنة كافية للدخول.',
