'Tfa_Guide_Enable_Title' => 'فعّلها من الملف الشخصي',
'Tfa_Guide_Enable_1' => 'افتح الملف الشخصي (قائمة الصورة الرمزية أعلى اليمين) وابحث عن بطاقة "المصادقة الثنائية".',
'Tfa_Guide_Enable_2' => 'انقر على "تفعيل" وأكّد بكلمة المرور الحالية.',
'Tfa_Guide_Enable_3' => 'امسح رمز QR بالتطبيق، أو اكتب المفتاح المعروض أسفله.',
'Tfa_Guide_Enable_4' => 'أدخل الرمز المكون من 6 أرقام الذي يعرضه التطبيق للإنهاء.',
'Tfa_Guide_Open_Profile' => 'فتح ملفي الشخصي',
'Tfa_Guide_Codes_Title' => 'احفظ رموز الاسترداد',
'Tfa_Guide_Codes_Text' => 'بعد الإعداد مباشرة، تُعرض 8 رموز استرداد مرة واحدة. كل رمز يحل محل رمز الهاتف مرة واحدة فقط — في حال فقدان الهاتف أو تعطله أو إعادة ضبطه. نزّلها أو انسخها واحفظها في مكان آمن بعيدًا عن الهاتف.',
'Tfa_Guide_Codes_Note' => 'أوشكت على النفاد؟ يستبدل خيار "رموز استرداد جديدة" في الملف الشخصي المجموعة بالكامل؛ وتتوقف الرموز القديمة عن العمل.',
'Tfa_Guide_Signin_Title' => 'تسجيل الدخول',
'Tfa_Guide_Signin_Text' => 'بعد البريد الإلكتروني وكلمة المرور، تطلب صفحة تسجيل الدخول الرمز الحالي من التطبيق. تتغير الرموز كل 30 ثانية وكل رمز يعمل مرة واحدة.',
'Tfa_Guide_Signin_Trust' => 'تحديد "لا تطلب الرمز مرة أخرى على هذا الجهاز" يتخطى الرمز على ذلك المتصفح لمدة :days يومًا.',
'Tfa_Guide_Signin_Recovery' => 'الهاتف ليس في متناولك؟ انقر على "استخدام رمز استرداد" واكتب أحد الرموز المحفوظة.',
'Tfa_Guide_Admin_Title' => 'للمسؤولين',
'Tfa_Guide_Require_Title' => 'اجعلها إلزامية',
'Tfa_Guide_Require_Text' => 'فعّل "اشتراط المصادقة الثنائية" في هذه البطاقة، ثم اختر الأدوار التي يجب أن تستخدمها — أو اترك القائمة فارغة لجميع المستخدمين. انقر على إرسال للحفظ.',
'Tfa_Guide_Require_Next' => 'لن يتم تسجيل خروج أحد. المستخدمون الذين لم يفعّلوا 2FA بعد يتم إرشادهم خلال الإعداد في صفحة تسجيل الدخول عند تسجيل دخولهم التالي، قبل الدخول، ويرون رموز الاسترداد هناك.',
'Tfa_Guide_Require_Note' => 'لا يمكن للمستخدمين المشترط عليهم استخدامها إيقافها من ملفهم الشخصي.',
'Tfa_Guide_Trust_Title' => 'الأجهزة الموثوقة',
'Tfa_Guide_Trust_Text' => 'يحدد خيار "تذكر الأجهزة الموثوقة" المدة التي يمكن فيها للمتصفح تخطي الرمز بعد تسجيل دخول ناجح. اختر "اطلب الرمز دائمًا" لأجهزة الكمبيوتر المشتركة أو العامة مثل نقطة البيع في صالة المتجر.',
'Tfa_Guide_Trust_Note' => 'تقليل العدد يقصّر مدة الأجهزة الموثوقة حاليًا؛ وإيقاف 2FA أو إعادة تعيينها يُنسي جميع الأجهزة.',
'Tfa_Guide_Lost_Title' => 'فقدان الهاتف وعدم وجود رموز استرداد',
'Tfa_Guide_Lost_Text' => 'في صفحة المستخدمين، يظهر للمستخدمين الذين فعّلوا 2FA "مفعّلة" في عمود 2FA. يقوم زر الدرع في الإجراءات بإعادة تعيينها: يسجّل المستخدم الدخول بكلمة المرور فقط ثم يعيد إعداد التطبيق (أو يُطلب منه ذلك إذا كانت مطلوبة).',
'Tfa_Guide_Lost_Warn' => 'تأكد من هوية مقدم الطلب قبل إعادة التعيين — إذ تزيل إعادة التعيين الحماية التي توفرها 2FA لذلك الحساب.',
'Tfa_Guide_Open_Users' => 'فتح المستخدمين',
'Tfa_Guide_Mobile_Title' => 'تطبيق الجوال وAPI',
'Tfa_Guide_Mobile_Text' => 'يطلب تطبيق الجوال ونقطة نهاية رمز API الرمز نفسه. إذا كانت 2FA مطلوبة لمستخدم لم يُعدّها بعد، فعليه تسجيل الدخول عبر الويب مرة واحدة لإعدادها.',
'Tfa_Guide_Protect_Title' => 'حماية مدمجة',
'Tfa_Guide_Protect_1' => '5 رموز خاطئة تحظر إدخال الرموز لذلك المستخدم لمدة 15 دقيقة، بغض النظر عن إعدادات القفل أعلاه.',
'Tfa_Guide_Protect_2' => 'كل رمز وكل رمز استرداد يعمل مرة واحدة فقط.',
'Tfa_Guide_Protect_3' => 'عند تفعيل "تسجيل نشاط تسجيل الدخول"، تظهر الرموز الخاطئة في قائمة نشاط تسجيل الدخول باسم "رمز 2FA خاطئ".',
'Tfa_Guide_Trouble_Title' => 'استكشاف الأخطاء وإصلاحها',
'Tfa_Guide_Faq_Clock_Q' => '“هذا الرمز غير صالح” مع رمز جديد',
'Tfa_Guide_Faq_Clock_A' => 'على الأرجح ساعة الهاتف غير مضبوطة. تعتمد الرموز على الوقت: اضبط تاريخ ووقت الهاتف على التلقائي (وقت الشبكة)، ثم جرّب الرمز التالي.',
'Tfa_Guide_Faq_Phone_Q' => 'الانتقال إلى هاتف جديد',
'Tfa_Guide_Faq_Phone_A' => 'إما أن تستخدم ميزة النقل الخاصة بتطبيق المصادقة، أو أوقف 2FA من الملف الشخصي ثم فعّلها مجددًا بالهاتف الجديد (إذا كانت مطلوبة، فاطلب من المسؤول إعادة تعيينها بدلًا من ذلك).',
'Tfa_Guide_Faq_Locked_Q' => '“عدد كبير جدًا من الرموز غير الصالحة”',
'Tfa_Guide_Faq_Locked_A' => 'انتظر المدة المعروضة (حتى 15 دقيقة)، أو اطلب من المسؤول إعادة تعيين 2FA للمستخدم.',
'Tfa_Guide_Faq_Key_Q' => 'لا يستطيع أحد ممن فعّلوا 2FA تسجيل الدخول بعد نقل الخادم',
'Tfa_Guide_Faq_Key_A' => 'أسرار 2FA مشفرة باستخدام APP_KEY الموجود في ملف .env. احتفظ بنفس APP_KEY عند نقل التطبيق أو استعادته؛ وإذا تغيّر، فيجب على مسؤول لا يستخدم 2FA إعادة تعيين المستخدمين المتأثرين.',
'Tfa_Guide_Button' => 'الدليل',
'Tfa_Guide_Title' => 'دليل المصادقة الثنائية',
'Sec_2fa_Pending' => ':count لم يُعدّوها بعد',
'Sec_2fa_See_Who' => 'عرض من هم',
'Sec_2fa_Grace_Off' => 'بدون — الإعداد عند تسجيل الدخول التالي',
'Sec_2fa_Applied' => 'تم تسجيل خروج :count مستخدم/مستخدمين.',
'Tfa_Guide_Rollout_Title' => 'تعميمها على جميع المستخدمين',
'Tfa_Guide_Rollout_1' => 'فعّلها لحسابك أولًا (الملف الشخصي)، لتتعرف على الخطوات.',
'Tfa_Guide_Rollout_2' => 'أخبر فريقك بالتطبيق الذي يجب تثبيته وأن الإعداد يستغرق دقيقة عند تسجيل الدخول.',
'Tfa_Guide_Rollout_3' => 'فعّل "اشتراط المصادقة الثنائية"، واترك "مطلوبة لـ" فارغًا (= جميع المستخدمين)، واختر فترة سماح إن أردت. انقر على إرسال.',
'Tfa_Guide_Rollout_4' => 'انقر على "تسجيل خروج المستخدمين بدون 2FA" ليُعدّها المستخدمون المسجّلون حاليًا الآن بدلًا من تسجيل دخول لاحق. ستبقى أنت مسجّل الدخول.',
'Tfa_Guide_Rollout_5' => 'تابع التقدم باستخدام العدّاد في هذه البطاقة، أو فلتر "بحاجة إلى إعداد" في صفحة المستخدمين.',
'Tfa_Guide_Rollout_Note' => 'مع وجود فترة سماح، تعرض شاشة الإعداد خيار “ذكّرني لاحقًا” حتى الموعد النهائي؛ وبعده يصبح الإعداد مطلوبًا لتسجيل الدخول.',
'Tfa_Guide_Customers_Title' => 'حسابات العملاء (المتجر وبوابة العملاء)',
'Tfa_Guide_Customers_Text' => 'يمكن للعملاء حماية حساباتهم أيضًا. وهي اختيارية لكل عميل ولا تُفرض أبدًا: فعّلها من إعدادات المتجر ← التحكم في الوصول للتسجيل (المتجر الإلكتروني) ومن بوابة العملاء ← إعدادات البوابة (بوابة العملاء).',
'Tfa_Guide_Customers_1' => 'يفعّلها العملاء من حسابي (المتجر) أو الملف الشخصي (البوابة).',
'Tfa_Guide_Customers_2' => 'يختارون رمزًا يُرسل عبر البريد الإلكتروني — الأسهل، دون الحاجة إلى تطبيق — أو تطبيق مصادقة مع رموز استرداد.',
'Tfa_Guide_Customers_3' => 'تحتاج الرموز المرسلة بالبريد الإلكتروني إلى إعدادات بريد تعمل (الإعدادات ← إعدادات البريد). تنتهي صلاحيتها بعد 10 دقائق.',
'Tfa_Guide_Customers_4' => 'إيقاف الخيار لاحقًا يمنع عمليات الإعداد الجديدة؛ أما العملاء الذين يستخدمونها بالفعل فسيستمر طلب الرمز منهم ويمكنهم إيقافها بأنفسهم.',
'Tfa_Required_Grace_Notice' => 'يشترط المسؤول المصادقة الثنائية. يمكنك تأجيلها عند تسجيل الدخول حتى :date؛ وبعد ذلك يصبح الإعداد مطلوبًا.',
'Tfa_Filter_All' => '2FA: جميع المستخدمين',
'Tfa_Needs_Setup_Help' => 'مطلوبة من إعدادات النظام > الأمان؛ سيُطلب الإعداد عند تسجيل الدخول التالي.',
'Tfa_Needs_Setup' => 'بحاجة إلى إعداد',
'Tfa_Filter_On' => '2FA مفعّلة',
'Tfa_Filter_Off' => '2FA متوقفة',
'Tfa_Filter_Pending' => 'بحاجة إلى إعداد (مطلوبة)',
'Store_Customer_2fa' => 'التحقق بخطوتين',
